// src/pages/Schemes.jsx
import { useState } from "react";
import C from "../constants/colors";
import { SCHEMES } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";

function Schemes({ user, t }) {
  const [open, setOpen] = useState(null);

  // ── Translation strings ───────────────────────────────────────────────────
  const TX = {
    title:        t("schemes.title")       || "Government Schemes",
    subtitle:     t("schemes.subtitle")    || "Central & Tamil Nadu agricultural schemes",
    available:    t("schemes.available")   || "schemes available",
    eligibility:  t("schemes.eligibility") || "Eligibility Criteria",
    documents:    t("schemes.documents")   || "Required Documents",
    apply:        t("schemes.apply")       || "Apply →",
    portal:       t("schemes.portal")      || "Portal",
    active:       t("schemes.active")      || "Active",
    yourProfile:  t("schemes.yourProfile") || "Your profile",
    acres:        t("common.acres")        || "acres",
    variousCrops: t("common.loading") ? "" : "various crops",
  };

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>
        🏛️ {TX.title}
      </h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 6px" }}>{TX.subtitle}</p>

      {/* Profile summary banner */}
      <div style={{ padding: "10px 14px", background: C.pale, borderRadius: 8, fontSize: 13, color: C.bg2, marginBottom: 16 }}>
        ✅ {TX.yourProfile}: <strong>{user.name}</strong> • {user.district} • {user.landSize || "?"} {TX.acres} •{" "}
        {user.crops?.slice(0, 3).join(", ") || TX.variousCrops} —{" "}
        <strong>{SCHEMES.length} {TX.available}</strong>
      </div>

      {/* Scheme cards */}
      {SCHEMES.map((s, i) => (
        <Card key={i} style={{ marginBottom: 10 }}>

          {/* Header row — click to expand */}
          <div
            style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", cursor: "pointer" }}
            onClick={() => setOpen(open === i ? null : i)}
          >
            <div style={{ flex: 1, marginRight: 14 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
                <span style={{ fontSize: 14.5, fontWeight: 600, color: C.text }}>{s.name}</span>
                <Badge>{s.tag}</Badge>
                <Badge color={C.amber} bg={C.amberPale}>{s.amount}</Badge>
              </div>
              <div style={{ fontSize: 13, color: C.muted, lineHeight: 1.45 }}>{s.desc}</div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 7, alignItems: "flex-end", flexShrink: 0 }}>
              <Badge color={C.bg2}>● {TX.active}</Badge>
              <button
                onClick={e => { e.stopPropagation(); window.open(s.portal, "_blank"); }}
                style={{ padding: "6px 13px", background: C.bg2, color: "#fff", borderRadius: 7, border: "none", cursor: "pointer", fontSize: 12, fontWeight: 500 }}
              >
                {TX.apply}
              </button>
            </div>
          </div>

          {/* Expanded details */}
          {open === i && (
            <div style={{ marginTop: 12, paddingTop: 12, borderTop: `1px solid ${C.border}` }}>

              {/* Eligibility */}
              <div style={{ marginBottom: 10, padding: "10px 12px", background: C.pale, borderRadius: 8 }}>
                <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 4 }}>
                  ✅ {TX.eligibility}:
                </div>
                <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.5 }}>
                  {s.eligibility}
                </div>
              </div>

              {/* Documents */}
              <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 6 }}>
                📄 {TX.documents}:
              </div>
              <div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginBottom: 10 }}>
                {(s.docs || []).map(d => (
                  <span key={d} style={{ padding: "4px 10px", background: C.bg, borderRadius: 6, fontSize: 12, color: C.text, border: `1px solid ${C.border}` }}>
                    📄 {d}
                  </span>
                ))}
              </div>

              {/* Portal link */}
              <div style={{ fontSize: 12, color: C.muted }}>
                🌐 {TX.portal}:{" "}
                <a href={s.portal} target="_blank" rel="noreferrer" style={{ color: C.bg2 }}>
                  {s.portal}
                </a>
              </div>
            </div>
          )}
        </Card>
      ))}
    </div>
  );
}

export default Schemes;
